insert into public.courses (id, language, dialect, title, description, cefr_level, goal_tag, position, published, school, prerequisite_ids)
values ('bbbb0005-0000-4000-8000-000000000017', 'en', null, 'The Arab World: Culture & Civilization', 'A respectful tour of the Arab world as a cultural region: its lands and peoples, the Arabic language, a long literary and scientific heritage, and the art, food, and daily life that bind it together. Throughout, the course keeps the word Arab (an ethnic and linguistic identity) clearly apart from Muslim (a religious one). Structure and starting facts are drawn from Wikipedia, the free encyclopedia (CC BY-SA 4.0).', null, 'foundations', 69, true, 'humanities', '{}')
on conflict (id) do nothing;

insert into public.lessons (course_id, position, title, kind, body, grammar_notes_md, estimated_minutes)
select 'bbbb0005-0000-4000-8000-000000000017', v.pos, v.title, v.kind, v.body::jsonb, v.notes, v.mins
from (values
  (1, 'Diagnostic: where are you now?', 'quiz', '{"questions":[{"prompt":"The word \"Arab\" refers most precisely to…","options":["a religion everyone in the region shares","an ethnic and linguistic identity centered on the Arabic language","a single country in North Africa","a political party founded in 1945"],"answer":1,"explanation":"Arab is an ethnolinguistic identity, defined above all by the Arabic language and shared culture — not by one country or one faith."},{"prompt":"The Arab League, founded in 1945, today has how many member states?","options":["10","15","22","40"],"answer":2,"explanation":"The League of Arab States has 22 members, spanning North Africa and Western Asia."},{"prompt":"Which statement is accurate about the relationship between \"Arab\" and \"Muslim\"?","options":["All Arabs are Muslims","All Muslims are Arabs","Most Muslims in the world are not Arab, and some Arabs are not Muslim","The two words mean exactly the same thing"],"answer":2,"explanation":"The largest Muslim populations are outside the Arab world, and the Arab world includes long-standing Christian and other communities. The terms are not interchangeable."},{"prompt":"The formal, shared written variety of Arabic used in news and education is usually called…","options":["a street dialect with no writing","Classical or Modern Standard Arabic","Latin","an invented language"],"answer":1,"explanation":"Modern Standard Arabic (fusha) is the shared formal register, descended from Classical Arabic, understood across the region in print and broadcast."},{"prompt":"One Thousand and One Nights is best described as…","options":["a legal code","a collection of interlinked folk tales and stories","a book of scientific proofs","a single short poem"],"answer":1,"explanation":"It is a famous framed collection of stories, told night after night by Scheherazade, gathered over centuries."},{"prompt":"The scholar whose Latinized name gives us the word \"algorithm\" and who shaped early algebra was…","options":["al-Khwarizmi","Julius Caesar","Marco Polo","Leonardo da Vinci"],"answer":0,"explanation":"Al-Khwarizmi, working in Baghdad, wrote the foundational treatise whose title gives us \"algebra\" and whose name gives us \"algorithm.\""},{"prompt":"The oud is a traditional Arab…","options":["kind of flatbread","pear-shaped stringed instrument","harvest festival","style of dance"],"answer":1,"explanation":"The oud is a fretless, pear-shaped lute at the heart of Arab music and an ancestor of the European lute."},{"prompt":"Naguib Mahfouz, the first Arabic-language writer to win the Nobel Prize in Literature, was from…","options":["Morocco","Egypt","Iraq","Lebanon"],"answer":1,"explanation":"The Egyptian novelist Naguib Mahfouz won the Nobel Prize in Literature in 1988, celebrated above all for his Cairo Trilogy."}]}'::jsonb, null, 10),
  (2, 'Lands and peoples: the Arab world and the Arab League', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Describe the Arab world as a cultural region, place its main geographic zones, name the body that links its states, and explain clearly why \"Arab\" and \"Muslim\" are not the same word. Warm-up: from the diagnostic, how many member states belong to the Arab League, and does that number describe a religion or a group of countries?"},{"heading":"The idea","text":"The Arab world is usually defined as the 22 countries whose shared language and culture are Arabic and which belong to the Arab League, founded in Cairo in 1945. It stretches in a long band from the Atlantic coast of Morocco and Mauritania, across North Africa, through the Nile Valley and the Levant, and down the Arabian Peninsula to the Arabian Sea and the Gulf. Geographically it mixes vast deserts, such as the Sahara and the Rub al-Khali, with fertile river valleys, long coastlines, and highland regions. Egypt is the most populous Arab country; Algeria and Saudi Arabia are among the largest by area. Crucially, \"Arab\" names a shared language and heritage, not a single religion. Most Arabs are Muslim, but the region is also home to ancient Christian communities and other faiths, while the majority of the world''s Muslims live outside the Arab world entirely, in countries such as Indonesia, Pakistan, and Nigeria."},{"heading":"Key figures & works","text":"The Arab League, or League of Arab States, began in 1945 with a small group of founding members, including Egypt, Iraq, Lebanon, Saudi Arabia, Syria, and Transjordan, and grew to its present 22 members as more states gained independence through the twentieth century. It coordinates on politics, economics, culture, and education, and its charter treats Arabic language and shared heritage as the thread tying members together. Great cities anchor the region''s identity: Cairo, the largest in the Arab world and a historic center of learning and film; Damascus and Baghdad, among the oldest continuously inhabited cities on earth; and Mecca and Medina in Saudi Arabia, which hold deep religious significance. These places show the region''s range, from Atlantic Morocco to the Gulf, as one cultural family rather than one uniform nation."},{"heading":"Your turn","text":"1) Roughly what two bodies of water mark the western and eastern ends of the Arab world? 2) In what year and city was the Arab League founded? 3) Name the most populous Arab country. 4) True or false: all Muslims are Arabs. 5) Give one example of a non-Muslim community found in the Arab world. Answers: 1) The Atlantic Ocean in the west and the Arabian Sea and the Gulf in the east. 2) 1945, in Cairo. 3) Egypt. 4) False — most Muslims worldwide are not Arab. 5) Arab Christian communities, such as the Copts of Egypt or Maronites of Lebanon."},{"heading":"Common mistakes & exit ticket","text":"Mistake: treating \"Arab\" and \"Muslim\" as synonyms — one is about language and culture, the other about faith. Mistake: imagining the Arab world as one country with one climate, when it spans two continents and many landscapes. Exit: (a) How many states belong to the Arab League? (b) Name one geographic feature shared by much of the region. Answers: 22; large desert regions such as the Sahara, alongside major rivers like the Nile and long coastlines."}]}'::jsonb, '"Arab" describes language and culture; "Muslim" describes religion. A person can be one, both, or neither — keep the two ideas separate.', 13),
  (3, 'The Arabic language: varieties, script, and calligraphy', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Tell apart the main varieties of Arabic, describe how the script works, and recognize why calligraphy became a central art form. Warm-up: what do we call the shared formal variety of Arabic used in newspapers and newscasts across the region?"},{"heading":"The idea","text":"Arabic is one language with several layers. Classical Arabic is the language of the Quran and of a vast body of early literature. From it grew Modern Standard Arabic, often called fusha, the shared formal variety used today in writing, education, broadcasting, and official speech across every Arab country. Alongside these sit the spoken dialects of daily life, which vary by region: Egyptian, Levantine, Gulf, Iraqi, and the Maghrebi dialects of North Africa among them. Speakers from distant countries may struggle with each other''s dialects yet read the same newspapers and share the same formal register. The script itself has 28 letters, is written from right to left, and is cursive, so letters join and change shape by position. Short vowels are usually left unwritten and supplied by the reader. Arabic script also serves several other languages, such as Persian and Urdu, which adapted it with extra letters."},{"heading":"Key figures & works","text":"Because Arabic script is flowing and its most revered text is a book, calligraphy, rather than figurative painting, became the supreme visual art of the Arab world. Over centuries scribes developed distinct styles: angular Kufic, used in early manuscripts and on buildings; rounded, highly legible Naskh, long favored for copying books; the stately, ornamental Thuluth seen on monuments; and the dense, decorative Diwani used in royal chanceries. A single word could be shaped into a bird, a boat, or an intricate pattern. Calligraphers trained for years under a master and received an ijaza, a certificate of permission to teach. Written Arabic and its aesthetics thus carry both practical and sacred weight, which is why you find elegant script woven into mosque walls, book covers, ceramics, and modern logos alike. The letters are not only read; they are admired."},{"heading":"Your turn","text":"1) What is the everyday name for Modern Standard Arabic? 2) In which direction is Arabic written? 3) How many letters are in the Arabic alphabet? 4) Name two regional dialect groups. 5) Name one calligraphic style. Answers: 1) Fusha. 2) Right to left. 3) 28. 4) Any two of: Egyptian, Levantine, Gulf, Iraqi, Maghrebi. 5) Any one of: Kufic, Naskh, Thuluth, Diwani."},{"heading":"Common mistakes & exit ticket","text":"Mistake: assuming all Arabic speakers understand every dialect perfectly, when dialects can differ sharply even as fusha unites them in writing. Mistake: thinking calligraphy is mere decoration, when it is a trained art with named schools and a teaching tradition. Exit: (a) Name the formal shared variety of Arabic. (b) Why did calligraphy rise to such prominence? Answers: Modern Standard Arabic (fusha); because the script is flowing and its most honored text is written, so beautiful writing became the leading visual art."}]}'::jsonb, 'Arabic reads right to left, and most letters change shape depending on whether they sit at the start, middle, or end of a word — the writing is naturally cursive.', 14),
  (4, 'The classical heritage and the golden age of learning', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Trace Arab culture from its pre-Islamic roots through the classical caliphates to a remarkable age of scholarship, and name a few of the thinkers whose work shaped the wider world. Warm-up: which Baghdad institution became famous as a hub for translating and advancing knowledge?"},{"heading":"The idea","text":"Long before the rise of Islam in the seventh century, the Arabian Peninsula hosted rich civilizations: the Nabataeans who carved Petra, the incense kingdoms of the south such as Saba, and Bedouin societies whose oral poetry was already prized. This pre-Islamic period, later called the Jahiliyya, gave Arabic a mature poetic tradition. With the rapid spread of Islam, Arabic became the language of a vast realm under the Umayyad caliphate, centered on Damascus, and then the Abbasid caliphate, centered on Baghdad. Cities swelled, trade reached from Spain to China, and a shared written language connected scholars across three continents. This classical age set the stage for an extraordinary flowering of science, philosophy, and the arts, often called the golden age, lasting from roughly the eighth to the fourteenth centuries."},{"heading":"Key figures & works","text":"In Baghdad, the House of Wisdom gathered manuscripts and scholars who translated Greek, Persian, and Indian works into Arabic and then pushed far beyond them. Al-Khwarizmi systematized algebra and lent his name to the word algorithm. Ibn al-Haytham, known in Latin as Alhazen, transformed optics and argued for testing ideas against observation. In medicine, Ibn Sina (Avicenna) wrote the Canon of Medicine, a reference text for centuries, while al-Razi advanced clinical practice. Philosophers such as al-Kindi and Ibn Rushd (Averroes) debated reason and faith, and Ibn Rushd''s commentaries on Aristotle later shaped European universities. Al-Biruni measured the earth and studied distant cultures. Much later, the historian Ibn Khaldun wrote the Muqaddima, an early work of social theory. Many of these figures were Persian or Central Asian by background, yet they wrote in Arabic, which is why their achievements belong to this shared heritage."},{"heading":"Your turn","text":"1) What name is given to the pre-Islamic period? 2) Which city was the Abbasid capital and the home of the House of Wisdom? 3) Who is credited with systematizing algebra? 4) What is Ibn Sina''s most famous medical work? 5) Name the historian who wrote the Muqaddima. Answers: 1) The Jahiliyya. 2) Baghdad. 3) Al-Khwarizmi. 4) The Canon of Medicine. 5) Ibn Khaldun."},{"heading":"Common mistakes & exit ticket","text":"Mistake: assuming every golden-age scholar was ethnically Arab, when many were Persian or Central Asian writing in Arabic. Mistake: thinking the region had no culture before Islam, when a strong poetic and urban heritage already existed. Exit: (a) Name the Baghdad center of translation and learning. (b) Give one scholar and the field they advanced. Answers: the House of Wisdom; for example, Ibn al-Haytham in optics, or al-Khwarizmi in mathematics."}]}'::jsonb, 'Many golden-age scholars were not ethnically Arab, yet they wrote in Arabic — the shared scholarly language of the time — which is why their work belongs to this heritage.', 14),
  (5, 'Checkpoint 1', 'quiz', '{"questions":[{"prompt":"The Arab world stretches roughly from the Atlantic coast of North Africa eastward to…","options":["the Pacific Ocean","the Arabian Sea and the Gulf","the Baltic Sea","the Caribbean"],"answer":1,"explanation":"The region runs from Morocco and Mauritania in the west to the Arabian Peninsula and the Gulf in the east."},{"prompt":"Which is the best description of Modern Standard Arabic (fusha)?","options":["an extinct language no one reads","the shared formal variety used in writing, news, and education","a single local street dialect","a dialect of English"],"answer":1,"explanation":"Fusha is the common formal register understood across the Arab world, distinct from the many spoken dialects."},{"prompt":"Arabic script is written…","options":["left to right","right to left","only vertically","in separate, never-joined letters"],"answer":1,"explanation":"Arabic reads right to left and is cursive, with letters joining and changing shape by position."},{"prompt":"In which city did the House of Wisdom flourish during the golden age?","options":["Baghdad","Rome","London","Beijing"],"answer":0,"explanation":"The House of Wisdom was a renowned center of translation and scholarship in Abbasid Baghdad."},{"prompt":"Ibn Sina (Avicenna) is especially remembered for his influential work in…","options":["shipbuilding","medicine","glassblowing","cartography alone"],"answer":1,"explanation":"His Canon of Medicine served as a leading medical reference for centuries."},{"prompt":"Which statement about calligraphy in the Arab world is accurate?","options":["it was a minor craft with no training","it became a leading visual art with named styles and a teaching tradition","it was banned everywhere","it used only a single fixed style"],"answer":1,"explanation":"Calligraphy rose to the top rank of the visual arts, with styles like Kufic, Naskh, and Thuluth and formal master-to-student training."}]}'::jsonb, null, 8),
  (6, 'Literature and poetry: from the odes to Mahfouz', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Follow Arabic literature from pre-Islamic odes through the classical masters to the modern novel and poem, and name landmark works and writers. Warm-up: what framed collection of tales features a storyteller spinning a new story each night to stay alive?"},{"heading":"The idea","text":"Poetry has been called the public record of the Arabs, and the tradition runs very deep. The pre-Islamic Mu''allaqat, or suspended odes, were long formal poems so admired that legend says they were hung for display. The classical period refined set forms: the qasida, a long ode moving from a nostalgic opening to praise or reflection, and the ghazal, a shorter love lyric. Prose flourished too, most famously in One Thousand and One Nights, a collection of interlinked folk tales framed by Scheherazade, who delays her fate by telling the king a new story each night. These works circulated across the whole Arabic-reading world and, in translation, shaped storytelling far beyond it. Arabic literature, in short, reaches from desert oral verse to printed novels without losing its love of the well-turned line."},{"heading":"Key figures & works","text":"Among classical poets, al-Mutanabbi is often ranked the greatest, prized for sweeping confidence and sharp wit, while Abu Nuwas wrote with daring wit in Abbasid Baghdad. In the modern era, poetry renewed itself: the Palestinian Mahmoud Darwish gave voice to exile and homeland, the Syrian Nizar Qabbani wrote frank love poetry and political verse, and Adonis pushed Arabic poetry toward bold modern forms. The modern novel arrived powerfully with Egypt''s Naguib Mahfouz, whose Cairo Trilogy follows a Cairo family across generations; in 1988 he became the first Arabic-language writer to win the Nobel Prize in Literature. Other novelists, such as Tayeb Salih of Sudan with Season of Migration to the North, brought the Arab world''s encounters with the wider world into fiction. Together these writers carry an old devotion to language into contemporary forms."},{"heading":"Your turn","text":"1) What are the Mu''allaqat? 2) Who narrates One Thousand and One Nights? 3) Name the classical poet often called the greatest. 4) Which Egyptian novelist won the 1988 Nobel Prize in Literature? 5) Name one modern Arab poet. Answers: 1) The pre-Islamic suspended odes. 2) Scheherazade. 3) Al-Mutanabbi. 4) Naguib Mahfouz. 5) Any of Mahmoud Darwish, Nizar Qabbani, or Adonis."},{"heading":"Common mistakes & exit ticket","text":"Mistake: calling One Thousand and One Nights a single story, when it is a framed collection built up over centuries. Mistake: assuming Arabic literature is only ancient, when it has a vibrant modern novel and poetry scene. Exit: (a) Name the first Arabic-language Nobel laureate in Literature. (b) Define a qasida in one phrase. Answers: Naguib Mahfouz; a long, formal ode."}]}'::jsonb, 'In Arabic criticism, a qasida is a long, formal ode and a ghazal is a shorter love poem — form names, not just moods.', 13),
  (7, 'Art, architecture, and music', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Recognize the signature elements of Arab visual art and architecture, and describe the sound of Arab music, including its main instrument and its modal system. Warm-up: which pear-shaped stringed instrument sits at the center of Arab music?"},{"heading":"The idea","text":"Arab visual art often favors pattern over portrait. Rather than figures, much classical art explores the arabesque, flowing plant-based designs, together with intricate geometry and, above all, calligraphy. These combine on tiles, carved wood, metalwork, and manuscript pages into dense, rhythmic surfaces. In architecture, recurring features include the horseshoe and pointed arch, the dome, the slender minaret, the shaded inner courtyard, the carved wooden screen called a mashrabiya, and the honeycomb vaulting known as muqarnas. Landmark buildings range from the Great Mosque of Damascus to the palaces and gardens of Moorish Spain, such as the Alhambra, which grew from this shared artistic language. The guiding instinct is to turn surface and space into ordered, contemplative beauty, where light, shadow, water, and repeated motifs do the work that statues might do in other traditions."},{"heading":"Key figures & works","text":"Arab music is built on the maqam, a system of melodic modes that includes microtones, intervals smaller than the half-steps of a piano, which gives the music its distinctive, expressive color. Rhythms follow named cycles called iqa. The leading instrument is the oud, a fretless, pear-shaped lute whose warm tone anchors ensembles and which traveled to Europe to become the lute. Around it play the qanun, a plucked zither; the ney, a reed flute; and various drums such as the riqq and darbuka. Performers prize tarab, a state of deep musical ecstasy shared between artist and audience, often reached through improvisation. The towering modern figure is the Egyptian singer Umm Kulthum, whose decades-long career and marathon concerts made her one of the most beloved artists in the Arab world, a voice still heard everywhere today."},{"heading":"Your turn","text":"1) What is an arabesque? 2) Name two features of Arab architecture. 3) What is a maqam? 4) Which instrument is the heart of Arab music? 5) Name the famous Egyptian singer discussed here. Answers: 1) A flowing, plant-based decorative pattern. 2) Any two of: dome, minaret, courtyard, horseshoe or pointed arch, mashrabiya, muqarnas. 3) A melodic mode, including microtones. 4) The oud. 5) Umm Kulthum."},{"heading":"Common mistakes & exit ticket","text":"Mistake: thinking Arab art avoids all images for one simple reason, when the strong preference for pattern and calligraphy is a rich artistic choice with many regional exceptions. Mistake: confusing maqam (melody) with rhythm, which is handled by iqa. Exit: (a) Name the central instrument of Arab music. (b) What quality do musicians aim to create with listeners? Answers: the oud; tarab, a shared state of musical ecstasy."}]}'::jsonb, 'In Arab music, maqam names a melodic mode (which notes and how to move among them), while iqa names a rhythmic cycle — melody and rhythm are described separately.', 13),
  (8, 'Food, family, and hospitality', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Describe the staples of Arab cuisine, explain the deep value placed on hospitality, and connect food and family to broader social customs and festivals. Warm-up: what word describes a spread of many small shared dishes served at the start of a meal?"},{"heading":"The idea","text":"Food in the Arab world is above all shared. A meal often begins with mezze, an array of small dishes such as hummus, baba ghanoush, tabbouleh, and stuffed vine leaves, set out for everyone to reach. Bread appears at nearly every table and is treated with respect. Regional specialties abound: kibbeh and shawarma in the Levant, mansaf of lamb and yogurt in Jordan, slow-steamed couscous across the Maghreb, and spiced rice dishes like kabsa in the Gulf. Dates and strong, often cardamom-scented coffee or sweet tea mark welcome and celebration. Underlying all of this is karam, the prized value of generosity. A guest is honored, pressed to eat more, and never allowed to feel a burden; refusing hospitality can itself seem impolite. Sharing food is how relationships are built and maintained."},{"heading":"Key figures & works","text":"Hospitality and food sit within a wider web of family and community. Extended families are central, elders are respected, and major life events, weddings, births, and homecomings, are marked by large gatherings and generous feasts. Festivals weave through the year, and here the earlier distinction matters: the two Eids, Eid al-Fitr at the end of Ramadan and Eid al-Adha, are Muslim religious holidays widely celebrated in the region, while Arab Christians mark Christmas and Easter, and many communities also enjoy secular and seasonal festivals. During Ramadan, Muslim families break the daily fast with the iftar meal, often shared across neighborhoods. Coffeehouses, markets, and the evening stroll are everyday social institutions. Across these settings runs a common thread: the table and the family circle are where culture is passed on, generation to generation."},{"heading":"Your turn","text":"1) Name two dishes commonly found in mezze. 2) What value describes Arab generosity to guests? 3) Name the North African steamed grain dish. 4) Which two festivals are Muslim religious holidays? 5) What meal breaks the daily fast during Ramadan? Answers: 1) Any two of hummus, baba ghanoush, tabbouleh, stuffed vine leaves. 2) Karam (hospitality or generosity). 3) Couscous. 4) Eid al-Fitr and Eid al-Adha. 5) Iftar."},{"heading":"Common mistakes & exit ticket","text":"Mistake: assuming every festival in the Arab world is religious, when cultural, seasonal, and Christian celebrations also take place. Mistake: treating hospitality as mere politeness, when karam is a core social value. Exit: (a) Name the value of generosity toward guests. (b) Which holiday ends the month of Ramadan? Answers: karam; Eid al-Fitr."}]}'::jsonb, 'A "mezze" is a spread of many small shared dishes — the word is plural in spirit, describing a table, not a single plate.', 12),
  (9, 'Key terms', 'vocab', '{"items":[{"term":"Arab vs. Muslim","translation":"Arab is an ethnic and linguistic identity; Muslim is a religious one — related but not the same","example":"An Egyptian Copt may be Arab but Christian; an Indonesian is often Muslim but not Arab."},{"term":"fusha","translation":"Modern Standard Arabic, the shared formal variety used in writing, news, and education","example":"A newscaster in Morocco and one in Iraq both read the news in fusha."},{"term":"Arab League","translation":"the League of Arab States, founded in 1945, now with 22 member countries","example":"The Arab League links nations from Morocco to the Gulf through shared language and culture."},{"term":"Mu''allaqat","translation":"the celebrated pre-Islamic \"suspended odes,\" long formal poems","example":"Students of classical poetry still read the Mu''allaqat for their craft."},{"term":"House of Wisdom","translation":"the Baghdad center of translation and scholarship during the golden age","example":"At the House of Wisdom, Greek and Indian works were translated and extended."},{"term":"maqam","translation":"a melodic mode in Arab music, using intervals that include microtones","example":"The musician chose a maqam that gave the piece a longing, bittersweet color."},{"term":"karam","translation":"the deeply held value of generosity and hospitality toward guests","example":"Out of karam, the host kept refilling the plates until everyone was full."}]}'::jsonb, null, 9),
  (10, 'The modern Arab world: diversity, diaspora, and global reach', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Describe the diversity of the contemporary Arab world, explain what the Arab diaspora is, and give examples of Arab cultural contributions that have spread worldwide. Warm-up: given 22 countries across two continents, why is it a mistake to speak of a single, uniform \"Arab culture\"?"},{"heading":"The idea","text":"The modern Arab world is strikingly diverse. Its 22 countries range from densely populated river valleys to oil-rich Gulf states and mountainous North African nations, each with its own dialect, cuisine, music, and history. Religion varies too: alongside a Muslim majority there are long-standing Christian communities and other groups. Politically and economically the region spans great contrasts, and within any one country there is further variety of city and countryside, generation and outlook. This is why careful observers speak of Arab cultures in the plural as much as a single shared heritage. The thread that connects them remains the Arabic language and a common literary and artistic inheritance, but that shared frame holds a wide range of ways of living, so generalizing about the whole region flattens a rich and changing reality."},{"heading":"Key figures & works","text":"For more than a century, migration has carried Arab communities around the globe, forming a large diaspora, historically called the mahjar, with major populations in the Americas, Europe, West Africa, and beyond. Early emigrant writers in the Americas, such as the Lebanese-American Khalil Gibran, author of The Prophet, blended Arab and Western sensibilities and reached vast audiences. Today Arab and Arab-descended artists, scientists, chefs, athletes, and scholars contribute worldwide. Arab cuisine has gone global, with hummus and shawarma now familiar far from home; Arab music and film, long centered on Cairo and Beirut, reach international listeners and viewers; and Arabic words embedded in other languages, from algebra to coffee to sugar, quietly record centuries of exchange. The contemporary Arab world is thus both deeply rooted and highly connected, shaping and shaped by the wider world."},{"heading":"Your turn","text":"1) Why is \"a single Arab culture\" an oversimplification? 2) What is the Arab diaspora, and what older term names it? 3) Name the Lebanese-American author of The Prophet. 4) Give one Arab dish now eaten worldwide. 5) Name one everyday English word borrowed from Arabic. Answers: 1) Because the 22 countries differ widely in dialect, religion, cuisine, and history. 2) Arab communities living outside the region; the mahjar. 3) Khalil Gibran. 4) Hummus or shawarma. 5) Any of algebra, coffee, sugar, cotton, or algorithm."},{"heading":"Common mistakes & exit ticket","text":"Mistake: assuming all Arab countries are alike, when they differ sharply in geography, religion, dialect, and economy. Mistake: forgetting the global diaspora and the region''s long exchange with the rest of the world. Exit: (a) What word names Arab communities living abroad? (b) Give one global contribution of Arab culture. Answers: the diaspora (historically the mahjar); for example, cuisine such as hummus, or loanwords such as algebra and coffee."}]}'::jsonb, '"Diaspora" names communities living outside their ancestral region; in Arab history the related term is the mahjar, the lands of emigration.', 12)
) as v(pos, title, kind, body, notes, mins)
where not exists (
  select 1 from public.lessons l
  where l.course_id = 'bbbb0005-0000-4000-8000-000000000017' and l.position = v.pos
);
